# TEST project only: the made-up plans of the test site are deleted (Guy, walkthrough Q40) and two demo children get a plan of the new kind,
# from the version 2 bank, with a month of data for the spiral (observations marked to targets, incidents, 👍/👎, the therapist's ratings).
# c6 and c7 belong to therapist-test@ (scheduling-test-therapist.sql). Output: supabase/scheduling-test-plans-reset.sql
import io, json, glob, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
goals = {}
for f in sorted(glob.glob(os.path.join(ROOT, 'supabase', 'bank2', '*.json'))):
    for g in json.load(io.open(f, encoding='utf-8'))['goals']: goals[g['id']] = g
def plan_goal(g, age, tids, iids, now, sents_per=1):
    w = g['ages'][age]
    ts = [dict(id=t['id'], text=t['text'], staff=t['staff'], scale=t['scale'], now=now, target=4) for t in w['targets'] if t['id'] in tids]
    ints = [dict(id=i['id'], name=i['name'], what=i['what'], why=i['why'], freq=i['freq'], approach=i['approach'], sentences=i['sentences'][:sents_per]) for i in w['interventions'] if i['id'] in iids]
    return dict(id='demo-' + g['id'], title=g['title'], theme='', library_id=None, status='focus', focus=True, targets_list=ts, interventions_list=ints,
                strengths=g['strengths'][:2], planet_id=None, why_staff=g['line'], review_date=None, bank=dict(id=None, age=age),
                targets='\n'.join(t['staff'] for t in ts), interventions='\n'.join('• %s: %s' % (i['name'], i['what']) for i in ints), sentences='\n'.join(s for i in ints for s in i['sentences']))
p6 = dict(summary='דוגמה: נועם הגיע לפני חודשיים. כרגע הכי חשוב לעזור לו להירגע ברגעי כעס, בעזרת כלי שבחר.', avoid='לא להרים את הקול; לא לשלוח לפינה כעונש', calm='קופסת ההרגעה, נשימת בלון', gender='m',
          goals=[plan_goal(goals['reg-calm-tool'], '5-8', ['t1', 't3'], ['i1', 'i2', 'i4'], 2)])
p7 = dict(summary='דוגמה: מאיה הגיעה לפני חודש. כרגע הכי חשוב שתדע למי לפנות כשקשה.', avoid='לא להיעלם בלי להיפרד', gender='f',
          goals=[plan_goal(goals['safe-turn-adult'], '2-5', ['t1', 't2'], ['i1', 'i3', 'i4'], 1)])
def q(s): return "'" + str(s).replace("'", "''") + "'"
out = ["-- TEST project only (Guy, the walkthrough Q40, Q48): the made-up plans are deleted, and two demo children (c6, c7 of therapist-test@) get a plan of the new kind",
       "-- with a month of data for the spiral. Run after scheduling-v44.sql and scheduling-v44-bank.sql. Safe to run again. Generated by tools/test-demo-sql.py.",
       "do $$", "declare ins uuid; th uuid; k int;", "begin",
       "  delete from public.goal_scale where true; delete from public.intervention_feedback where true; delete from public.plan_videos where true;",
       "  delete from public.child_plan_versions where true; delete from public.child_plans where true;",
       "  select id into ins from public.staff where kind = 'instructor' and active order by sort_order nulls last limit 1;",
       "  select staff_id into th from public.staff_private where email = 'therapist-test@merkaz-cherum.local';",
       "  perform set_config('mercury.publishing', 'on', true);"]
for cid, plan in [('c6', p6), ('c7', p7)]:
    j = q(json.dumps(plan, ensure_ascii=False))
    out.append("  insert into public.child_plans (child_id, draft, review_date) values (%s, %s::jsonb, current_date + 60);" % (q(cid), j))          # (an insert is never published: plan_draft_stamp)
    out.append("  update public.child_plans set published = draft, published_version = 1, published_at = now() - interval '30 days', published_by = th where child_id = %s;" % q(cid))
    out.append("  insert into public.child_plan_versions (child_id, version, content, published_by, full_update) values (%s, 1, %s::jsonb, th, true);" % (q(cid), j))
    out.append("  insert into public.plan_videos (child_id, version, status, decided_at, decided_by) values (%s, 1, 'approved', now() - interval '29 days', th);" % q(cid))
    g = plan['goals'][0]
    for t in g['targets_list']:
        key = q(g['id'] + ':' + t['id'])
        out.append("  insert into public.goal_scale (child_id, goal_id, rated_on, value, by_staff) values (%s, %s, current_date - 28, %d, th), (%s, %s, current_date - 3, %d, th);" % (q(cid), key, t['now'], q(cid), key, t['now'] + 1))
        out.append("  for k in 1..10 loop insert into public.observations (child_id, author, text, goal_id, target_id, valence, created_at, seen_at) values (%s, ins, 'דוגמה: תצפית על היעד', %s, %s, case when k %% 3 = 0 then 'difficulty' else 'success' end, now() - (k * 2 || ' days')::interval, now()); end loop;" % (q(cid), q(g['id']), q(t['id'])))
    for i in g['interventions_list']:
        out.append("  insert into public.intervention_feedback (child_id, goal_id, intervention_id, staff_id, value, note, at) values (%s, %s, %s, ins, 'up', 'דוגמה: עבד', now() - interval '5 days'), (%s, %s, %s, ins, 'down', null, now() - interval '12 days');" % (q(cid), q(g['id']), q(i['id']), q(cid), q(g['id']), q(i['id'])))
    out.append("  insert into public.incidents (child_id, author, at, shift, kind, intensity, before, helped, goal_id, seen_at) values (%s, ins, now() - interval '9 days', 'צהריים', 'flooding', 2, '{מעבר}', %s, %s, now());" % (q(cid), q('{' + g['interventions_list'][0]['name'] + '}'), q(g['id'])))
out += ["  perform set_config('mercury.publishing', 'off', true);", "end $$;", "select 'test plans reset' as part, 'ok' as result, (select count(*) from public.child_plans) as plans;"]
io.open(os.path.join(ROOT, 'supabase', 'scheduling-test-plans-reset.sql'), 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print('ok')
